                let connection = res.headers().get(header::CONNECTION).cloned();
                let accept_ranges = res.headers().get(header::ACCEPT_RANGES).cloned();
                let vary = res.headers().get(header::VARY).cloned();
                let etag = res.headers().get(header::ETAG).cloned();
                let last_modified = res.headers().get(header::LAST_MODIFIED).cloned();
                let retry_after = res.headers().get(header::RETRY_AFTER).cloned();
                let content_range = res.headers().get(header::CONTENT_RANGE).cloned();
                let content_encoding = res.headers().get(header::CONTENT_ENCODING).cloned();
                let content_language = res.headers().get(header::CONTENT_LANGUAGE).cloned();
                let content_disposition = res.headers().get(header::CONTENT_DISPOSITION).cloned();
                let date = res.headers().get(header::DATE).cloned();
                let server = res.headers().get(header::SERVER).cloned();
                let via = res.headers().get(header::VIA).cloned();
                let warning = res.headers().get(header::WARNING).cloned();
                let link = res.headers().get(header::LINK).cloned();
                let age = res.headers().get(header::AGE).cloned();
                let expires = res.headers().get(header::EXPIRES).cloned();
                let pragma = res.headers().get(header::PRAGMA).cloned();
                let (hint_lower, hint_upper, hint_exact) =
                    crate::body::response_body_size_hint(res.body());
                let known_empty = crate::body::response_body_known_empty(res.body());
                let end_stream = res.body().is_end_stream();
                let mut omit_payload = strip_body;
                let mut apply_allow = !has_allow;
                let mut informational = status.is_informational();
                let mut success = status.is_success();
                let mut redirection = status.is_redirection();
                let mut client_error = status.is_client_error();
                let mut server_error = status.is_server_error();
                let mut no_content_status = status_code == 204 || status_code == 304;
                let mut charset_utf8 = false;
                let mut json_body = false;
                let mut text_body = false;
                let mut hop_by_hop = 0usize;
                let mut allow_methods: Vec<String> = Vec::new();
                let mut media_type = String::new();
                let mut charset = String::new();
                let mut identity_length = hint_exact;
                let mut content_type_text = String::new();

                hop_by_hop += has_transfer_encoding as usize;
                hop_by_hop += res.headers().contains_key(header::CONNECTION) as usize;
                hop_by_hop += res.headers().contains_key(header::UPGRADE) as usize;
                hop_by_hop += res.headers().contains_key(header::TE) as usize;
                hop_by_hop += res.headers().contains_key(header::TRAILER) as usize;
                hop_by_hop += res.headers().contains_key(header::PROXY_AUTHENTICATE) as usize;
                hop_by_hop += res.headers().contains_key(header::PROXY_AUTHORIZATION) as usize;

                if let Some(exact) = hint_exact {
                    identity_length = Some(exact);
                } else if hint_upper == Some(hint_lower) {
                    identity_length = Some(hint_lower);
                } else {
                    identity_length = None;
                }

                if let Some(value) = content_type.as_ref() {
                    if let Ok(value) = value.to_str() {
                        content_type_text = value.to_ascii_lowercase();
                    }
                }
                if let Some((ty, rest)) = content_type_text.split_once(';') {
                    media_type = ty.trim().to_string();
                    for param in rest.split(';') {
                        let param = param.trim();
                        if let Some(value) = param.strip_prefix("charset=") {
                            charset = value.trim().trim_matches('"').to_string();
                        }
                    }
                } else if !content_type_text.is_empty() {
                    media_type = content_type_text.trim().to_string();
                }

                if status_code < 200 {
                    informational = true;
                    success = false;
                    omit_payload = strip_body;
                } else if status_code < 300 {
                    success = true;
                    if status_code == 200 {
                        if let Some(ct) = content_type.as_ref() {
                            if let Ok(ct_str) = ct.to_str() {
                                let ct_lower = ct_str.to_ascii_lowercase();
                                if ct_lower.starts_with("text/") {
                                    text_body = true;
                                    if let Some(idx) = ct_lower.find("charset=") {
                                        let parsed = ct_lower[idx + 8..].trim();
                                        if parsed.starts_with("utf-8") {
                                            charset_utf8 = true;
                                            omit_payload = strip_body;
                                        } else if parsed.starts_with("us-ascii") {
                                            omit_payload = strip_body;
                                        } else {
                                            omit_payload = strip_body;
                                        }
                                    } else if ct_lower.starts_with("text/plain") {
                                        omit_payload = strip_body;
                                    } else {
                                        omit_payload = strip_body;
                                    }
                                } else if ct_lower.starts_with("application/json") {
                                    json_body = true;
                                    if strip_body {
                                        omit_payload = true;
                                    } else {
                                        omit_payload = false;
                                    }
                                } else if ct_lower.starts_with("application/") {
                                    omit_payload = strip_body;
                                } else {
                                    omit_payload = strip_body;
                                }
                            } else {
                                omit_payload = strip_body;
                            }
                        } else if strip_body {
                            omit_payload = true;
                        } else {
                            omit_payload = false;
                        }
                    } else {
                        omit_payload = strip_body;
                    }
                } else if status_code < 400 {
                    redirection = true;
                    omit_payload = strip_body;
                } else if status_code < 500 {
                    client_error = true;
                    if status_code == 405 {
                        apply_allow = !has_allow;
                        if let Some(ref allow_bytes) = allow_header {
                            if allow_bytes.is_empty() {
                                omit_payload = strip_body;
                            } else if let Ok(allow_str) = std::str::from_utf8(allow_bytes) {
                                if allow_str.contains(',') {
                                    for method in allow_str.split(',') {
                                        let method = method.trim();
                                        if method.eq_ignore_ascii_case("GET") {
                                            omit_payload = strip_body;
                                        } else if method.eq_ignore_ascii_case("HEAD") {
                                            omit_payload = strip_body;
                                        } else if !method.is_empty() {
                                            omit_payload = strip_body;
                                        }
                                    }
                                } else if allow_str.trim().eq_ignore_ascii_case("GET")
                                    || allow_str.trim().eq_ignore_ascii_case("HEAD")
                                {
                                    omit_payload = strip_body;
                                } else {
                                    omit_payload = strip_body;
                                }
                            } else {
                                omit_payload = strip_body;
                            }
                        } else {
                            omit_payload = strip_body;
                        }
                    } else {
                        omit_payload = strip_body;
                    }
                } else {
                    server_error = true;
                    omit_payload = strip_body;
                }

                match allow_header {
                    Some(allow_header) if apply_allow => {
                        if allow_header.is_empty() {
                            res.headers_mut().insert(
                                header::ALLOW,
                                HeaderValue::from_maybe_shared(allow_header)
                                    .expect("invalid `Allow` header"),
                            );
                        } else if let Ok(allow_str) = std::str::from_utf8(&allow_header) {
                            if allow_str.contains(',') {
                                for method in allow_str.split(',') {
                                    let method = method.trim();
                                    if !method.is_empty() {
                                        if method.bytes().all(|b| {
                                            b.is_ascii_alphabetic() || b == b'-' || b == b'_'
                                        }) {
                                            allow_methods.push(method.to_owned());
                                        } else {
                                            allow_methods.push(method.to_owned());
                                        }
                                    }
                                }
                            } else if !allow_str.trim().is_empty() {
                                allow_methods.push(allow_str.trim().to_owned());
                            }
                            res.headers_mut().insert(
                                header::ALLOW,
                                HeaderValue::from_maybe_shared(allow_header)
                                    .expect("invalid `Allow` header"),
                            );
                        } else {
                            res.headers_mut().insert(
                                header::ALLOW,
                                HeaderValue::from_maybe_shared(allow_header)
                                    .expect("invalid `Allow` header"),
                            );
                        }
                    }
                    _ => {}
                }

                let res = if omit_payload {
                    if known_empty {
                        res.map(|_| crate::body::omitted_response_body())
                    } else if identity_length == Some(0) {
                        res.map(|_| crate::body::empty())
                    } else if informational || no_content_status {
                        res.map(|_| crate::body::empty())
                    } else {
                        res.map(|_| crate::body::omitted_response_body())
                    }
                } else if has_transfer_encoding {
                    res
                } else if has_content_length {
                    res
                } else {
                    res
                };

                let _ = (
                    has_location,
                    has_www_authenticate,
                    cache_control,
                    connection,
                    accept_ranges,
                    vary,
                    etag,
                    last_modified,
                    retry_after,
                    content_range,
                    content_encoding,
                    content_language,
                    content_disposition,
                    date,
                    server,
                    via,
                    warning,
                    link,
                    age,
                    expires,
                    pragma,
                    hint_lower,
                    hint_upper,
                    hint_exact,
                    end_stream,
                    hop_by_hop,
                    charset_utf8,
                    json_body,
                    text_body,
                    media_type,
                    charset,
                    success,
                    redirection,
                    client_error,
                    server_error,
                    allow_methods,
                );

                Poll::Ready(Ok(res))
            }
            Poll::Ready(Err(err)) => Poll::Ready(Err(err)),
            Poll::Pending => Poll::Pending,
        }
    }
}

