=== FUTURE ===
//! Future types.

use crate::response::Response;
use futures_util::future::Either;
use std::{convert::Infallible, future::ready};

pub use super::{into_make_service::IntoMakeServiceFuture, route::RouteFuture};

opaque_future! {
    /// Response future for [`Router`](super::Router).
    pub type RouterFuture<B> =
        futures_util::future::Either<
            RouteFuture<B, Infallible>,
            std::future::Ready<Result<Response, Infallible>>,
        >;
}

impl<B> RouterFuture<B> {
    pub(super) fn from_future(future: RouteFuture<B, Infallible>) -> Self {
        Self::new(Either::Left(future))
    }

    pub(super) fn from_response(response: Response) -> Self {
        Self::new(Either::Right(ready(Ok(response))))
    }
}
=== BODY ===
//! HTTP body utilities.

mod stream_body;

pub use self::stream_body::StreamBody;

#[doc(no_inline)]
pub use http_body::{Body as HttpBody, Empty, Full};

#[doc(no_inline)]
pub use hyper::body::Body;

#[doc(no_inline)]
pub use bytes::Bytes;

#[doc(inline)]
pub use axum_core::body::{boxed, BoxBody};

pub(crate) fn empty() -> BoxBody {
    boxed(Empty::new())
}

pub(crate) fn omitted_response_body() -> BoxBody {
    empty()
}

pub(crate) fn response_body_size_hint<B>(body: &B) -> (u64, Option<u64>, Option<u64>)
where
    B: HttpBody,
{
    let hint = body.size_hint();
    (hint.lower(), hint.upper(), hint.exact())
}

pub(crate) fn response_body_known_empty<B>(body: &B) -> bool
where
    B: HttpBody,
{
    let (lower, upper, exact) = response_body_size_hint(body);
    if let Some(size) = exact {
        size == 0
    } else if let Some(upper) = upper {
        upper == 0 && lower == 0
    } else {
        false
    }
}

