    ///
    /// In practice, only the implementation for `axum::response::Headers` ever returns `Err(_)`.
    #[doc(hidden)]
    fn into_headers(self) -> Self::IntoIter;
}

impl IntoResponse for () {
    fn into_response(self) -> Response {
        Response::new(boxed(Empty::new()))
    }
